function appliquerTraductions() {
  const lang = localStorage.getItem("lang") || "fr";

  document.querySelectorAll("[data-translate]").forEach((element) => {
    const key = element.dataset.translate;

    if (texts[lang][key]) {
      element.innerHTML = texts[lang][key];
    }
  });

   
}

document.addEventListener("DOMContentLoaded", () => {
  appliquerTraductions();
  const currentLang = localStorage.getItem("lang") || "fr";
  document.querySelectorAll(".drapeau").forEach((flag) => {
    if (flag.dataset.lang === currentLang) {
      flag.classList.add("active");
    }
    if (typeof loadSlide === "function") {
      loadSlide(current);
    }
  });
});

// page d'accueil

document.querySelectorAll(".flag").forEach((flag) => {
  flag.addEventListener("mouseover", () => {
    document.querySelectorAll("[data-translate]").forEach((element) => {
      const key = element.dataset.translate;
      if (texts[flag.dataset.lang][key]) {
        element.innerHTML = texts[flag.dataset.lang][key];
      }
    });
  });

  flag.addEventListener("click", () => {
    const lang = flag.dataset.lang;
    localStorage.setItem("lang", lang);
    window.location.href = "def.html";
  });
});

// page de définition
document.addEventListener("DOMContentLoaded", () => {
  appliquerTraductions();
  if (document.body.classList.contains("def")) {
    setTimeout(() => {
      document.getElementById("content").classList.add("show");
    }, 2000);
  }
});
function goNext() {
  location.href = "dual.html";
}

// menu drapeaux
const flags = document.querySelectorAll(".drapeau");
// appliquer la langue sauvegardée
const currentLang = localStorage.getItem("lang") || "fr";
flags.forEach((flag) => {
  if (flag.dataset.lang === currentLang) {
    flag.classList.add("active");
  }
  flag.addEventListener("click", () => {
    const lang = flag.dataset.lang;
    localStorage.setItem("lang", lang);
    // retire active partout
    flags.forEach((f) => f.classList.remove("active"));
    // active le drapeau choisi
    flag.classList.add("active");

    if (typeof loadSlide === "function") {
      loadSlide(current);
    }

    appliquerTraductions();

    
  });
});

